$cats['Satire & Dark Humor']['Satire & Dark Humor Social Satire'] = @('Living the Dream','Please Hold','Everything Must Go','The Great Consumer','The News Cycle','Influenced','Climbing the Ladder','Buy Replace Repeat','The Price of Success','Modern Religion','Work Harder','Mass Conformity','Privacy Sold Separately','Democracy Some Assembly Required','The Attention Economy','The Meeting That Could Have Been an Email','Certified Authority','Customer Satisfaction','The Personal Brand','Instant Gratification','The Algorithm Knows Best','The Paperwork Kingdom','Five Stars One Life','The Endless Upgrade','The Human Resource')
$cats['Satire & Dark Humor']['Satire & Dark Humor Dark Humor'] = @('Died Waiting for Approval','Dead Inside Great Outside','My Last Nerve','Existential Crisis Table for One','Professional Overthinker','Tomorrow Is Cancelled','My Life Is a Group Project','Emotionally Unavailable','Bad Decisions Excellent Stories','The Inner Gremlin','Sleep Is for the Living','Anxiety the Director''s Cut','Still a Work in Progress','The Ghost of Bad Taste','My Comfort Zone Is on Fire','The Apocalypse Has Been Rescheduled','Sorry for the Existence','The Human Error Message','I''m Fine This Is Fine','The Graveyard Shift','Worst-Case Scenario Champion','The Void Has Read Your Message','Nothing Is Under Control','A Beautiful Mess','The Final Boss Is Me')
$cats['Satire & Dark Humor']['Satire & Dark Humor Visual Irony'] = @('The Smiling Mask','The Cage With the Open Door','The Golden Prison','The Broken Compass','The Perfectly Imperfect Portrait','The Empty Throne','The Clock That Eats Time','The Shadow That Leads','The Ladder to Nowhere','The Key That Locks','The Mirror That Looks Away','The Open Book That Reads You','The Umbrella Underwater','The Lady or the Tiger','The Heart With a Door','The Mountain Inside the Cup','The Eye That Watches Itself','The Barbed Wire Rose','The Prison Built From Flowers','The Mask With No Face','The Infinite Staircase','The Fishbowl Ocean','The Flower Growing Backward','The Watch With No Hands','The Exit That Is an Entrance')
$cats['Satire & Dark Humor']['Satire & Dark Humor Pure Rebellion'] = @('The Unauthorized','Rebel Without a Cause','Smash the Pedestal','The Black Flag','Authority No Thanks','My Body My Rules','The System Can Wait','Outside the Lines','The Last Straw','I Will Not Be Filed','The Beautiful Disobedient','Break the Hierarchy','Make Trouble Worth Remembering')
$oldKinds = @()
$oldNames = @()
$hKinds = @()
$got = Read-Tree
if (-not $got) { "COULD NOT READ THE CATALOG - nothing written, run the block again" } else {
$tt = $got.tree
$backup = Join-Path $env:TEMP ("card-tree-backup-" + (Get-Date -Format "yyyyMMdd-HHmmss") + ".json")
[System.IO.File]::WriteAllText($backup, $got.raw, (New-Object System.Text.UTF8Encoding $false))
"  backup of the catalog saved first: " + $backup
$beforeCats = @($tt.subjects.PSObject.Properties).Count
$mine = @(); foreach ($c in $cats.Keys) { $mine += @($cats[$c].Keys) }
$oldSlugs = @{}; foreach ($o in $oldNames) { $oldSlugs[(& $slug $o)] = 1; $oldSlugs[(& $slug ($o + " in Service & Sacrifice Style"))] = 1 }
$taken = @{}; $tt.specific.PSObject.Properties | ? { ($mine -notcontains $_.Name) -and ($oldKinds -notcontains $_.Name) } | % { $_.Value | ? { $_ } | % { $taken[(& $slug $_)] = 1 } }
$firstRun = -not (@($mine) | ? { $tt.specific.PSObject.Properties[$_] })
$stop = $false
if ($firstRun) {
  $fl = (npx wrangler kv key list --namespace-id $ns --prefix "face:v1:" --remote 2>$null | Out-String)
  $nf = 0; foreach ($m in [regex]::Matches($fl, '"name":\s*"face:v1:([^"]+)"')) { if (-not $oldSlugs.ContainsKey($m.Groups[1].Value)) { $taken[$m.Groups[1].Value] = 1 }; $nf++ }
  "  " + $nf + " drawn designs checked so no new name overwrites one"
  if ($nf -lt 1000) { "  STOP - the list of drawn designs came back short, nothing written - run the block again"; $stop = $true }
} else { "  these sets are already in the catalog from the first run - names kept as they are" }
if (-not $stop) {
$final = @{}
foreach ($c in $cats.Keys) {
  $kinds = @($cats[$c].Keys)
  $had = @($tt.subjects.$c | ? { $_ })
  if ($c -eq 'Service & Sacrifice') {
    $gone = 0; foreach ($k in $oldKinds) { if ($tt.specific.PSObject.Properties[$k]) { $tt.specific.PSObject.Properties.Remove($k); $gone++ } }
    "  Service & Sacrifice: " + $gone + " old sets REMOVED, the 10 branch sets put in their place"
    $keep = @($had | ? { ($oldKinds -notcontains $_) -and ($kinds -notcontains $_) })
    $newList = @($kinds + $keep)
  } else {
    "  " + $c + " had " + $had.Count + " sets before"
    $newList = @($had + @($kinds | ? { $had -notcontains $_ }))
  }
  if ($tt.subjects.PSObject.Properties[$c]) { $tt.subjects.$c = $newList } else { $tt.subjects | Add-Member -NotePropertyName $c -NotePropertyValue $newList }
  foreach ($k in $kinds) {
    if ($tt.specific.PSObject.Properties[$k]) { $names = @($tt.specific.$k); foreach ($nn in $names) { $o = ($nn -replace (' in ' + [regex]::Escape($c) + ' Style$'), ''); $final[$o] = $nn } }
    else {
      $names = @($cats[$c][$k] | % { $o = $_; if ($taken.ContainsKey((& $slug $o))) { $nn = $o + " in " + $c + " Style"; "  RENAMED: " + $nn | Out-Host } else { $nn = $o }; $taken[(& $slug $nn)] = 1; $final[$o] = $nn; $nn })
      $tt.specific | Add-Member -NotePropertyName $k -NotePropertyValue $names
    }
  }
}
$json = $tt | ConvertTo-Json -Depth 20 -Compress
$check = $json | ConvertFrom-Json
$afterCats = @($check.subjects.PSObject.Properties).Count
if ($afterCats -lt $beforeCats -or $json.Length -lt ($got.raw.Length * 0.9)) { "  SAFETY STOP - the new catalog looks smaller than the old one, nothing written" } else {
$tmp = Join-Path $env:TEMP "card-tree-new.json"
[System.IO.File]::WriteAllText($tmp, $json, (New-Object System.Text.UTF8Encoding $false))
npx wrangler kv key put --namespace-id $ns "card:tree" --path $tmp --remote 2>$null | Out-Null
"  catalog written in ONE save: " + $beforeCats + " categories before, " + $afterCats + " after"
$kv = New-Object System.Collections.ArrayList
foreach ($c in $cats.Keys) { foreach ($k in $cats[$c].Keys) {
  $ks = & $slug $k
  [void]$kv.Add(@{ key = "render:" + $ks; value = "The tattoo in both panels is identical." })
  [void]$kv.Add(@{ key = "shape:" + $ks; value = "3:2" })
  [void]$kv.Add(@{ key = "split:" + $ks; value = "yes" })
  foreach ($o in $cats[$c][$k]) { [void]$kv.Add(@{ key = "build:" + (& $slug $final[$o]); value = $b[$o] }) }
} }
$hn = 0
foreach ($k in $hKinds) { foreach ($nn in @($tt.specific.$k)) { if ($nn) { $o = ($nn -replace " in Where I'm From Style$", ""); if ($h.ContainsKey($o)) { [void]$kv.Add(@{ key = "build:" + (& $slug $nn); value = $h[$o] }); $hn++ } else { "  NO NEW WORDING FOR: " + $nn } } } }
$bf = Join-Path $env:TEMP "build-descs.json"
[System.IO.File]::WriteAllText($bf, (ConvertTo-Json -InputObject @($kv) -Depth 3 -Compress), (New-Object System.Text.UTF8Encoding $false))
"  saving " + $kv.Count + " settings and descriptions in one bulk write (" + $hn + " of them are the new Where I'm From wording)..."
$res = (npx wrangler kv bulk put --namespace-id $ns $bf --remote 2>&1 | Out-String)
if ($res -match 'Success') { "  bulk write OK" } else { "  BULK WRITE PROBLEM - send me this:"; $res.Substring([Math]::Max(0, $res.Length - 600)) }
"  waiting 70 seconds so every server sees the new catalog..."
Start-Sleep -Seconds 70
$got2 = Read-Tree
if ($got2) { foreach ($c in $cats.Keys) { $cnt = 0; foreach ($k in $cats[$c].Keys) { $cnt += @($got2.tree.specific.$k | ? { $_ }).Count }; "  " + $c + ": " + $cnt + " of 88 cards in the catalog" } } else { "  could not re-read the catalog to check - run the draw anyway, it checks the count itself" }
"== BUILD DONE - the draw starts next =="
} } }
